 ap=argparse.ArgumentParser(); ap.add_argument('--root',type=Path,required=True); ap.add_argument('--output',type=Path,required=True); ap.add_argument('--commit',required=True); a=ap.parse_args(); r=a.root; d=json.loads((r/'results/run_provenance_v79.json').read_text()); d['schema']='run_provenance_v80'; d['created_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat(); d['github_main_commit']=a.commit; d['source_alignment']='results/main_nersc_source_alignment_v39.json'; d['source_alignment_sha256']=sha(r/'results/main_nersc_source_alignment_v39.json'); d['stage_progress']='results/stage_progress_v24.json'; d['stage_progress_sha256']=sha(r/'results/stage_progress_v24.json'); d['stage8_holdout_report']='results/stage8_holdout_validation_report_v7.json'; d['stage8_holdout_report_sha256']=sha(r/'results/stage8_holdout_validation_report_v7.json'); d['corrected_bphi_calibration']='results/bphi_normalization_refit_58197556/calibration.json'; d['corrected_bphi_calibration_sha256']=sha(r/'results/bphi_normalization_refit_58197556/calibration.json'); d['corrected_bphi_run_provenance']='results/bphi_normalization_refit_58197556/run_provenance.json'; d['corrected_bphi_run_provenance_sha256']=sha(r/'results/bphi_normalization_refit_58197556/run_provenance.json'); d['corrected_bphi_audit']='results/bphi_disjoint_response_audit_v3_58197556.json'; d['corrected_bphi_audit_sha256']=sha(r/'results/bphi_disjoint_response_audit_v3_58197556.json'); d['batch_outputs']['source_alignment_v39']='results/main_nersc_source_alignment_v39.json'; d['batch_outputs']['stage_progress_v24']='results/stage_progress_v24.json'; d['batch_outputs']['stage8_holdout_report_v7']='results/stage8_holdout_validation_report_v7.json'; d['batch_outputs']['corrected_bphi_calibration']='results/bphi_normalization_refit_58197556/calibration.json'; d['status']='PARTIAL'; a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(json.dumps(d,indent=2)+'\n'); print(json.dumps({'status':d['status'],'commit':a.commit}))
